// dnsRecordBindingWhereR holds the relationship-based filters of
// dnsRecordBindingWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type dnsRecordBindingWhereR[Q sqlite.Filterable] struct {
	cols dnsRecordBindingColumns
}

// HasGameServer filters parents that have a matching GameServer using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to GameServers).
func (w dnsRecordBindingWhereR[Q]) HasGameServer(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(GameServers.NameExpr()),
		sm.Where(GameServers.Columns.ID.EQ(w.cols.GameServerID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// NULL-tolerant scan buffer for dnsRecordBindingScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type dnsRecordBindingPreloadBuf struct {
	GameServerID          null.Val[string]
	RelativeName          null.Val[string]
	OwnedProviderRecordID null.Val[string]
	OwnedFQDN             null.Val[string]
	OwnedRecordType       null.Val[string]
	OwnedValue            null.Val[string]
	OwnedTTL              null.Val[int64]
}

// dnsRecordBindingScanMapperNullable maps the preloaded dnsRecordBinding
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func dnsRecordBindingScanMapperNullable(prefix string) scan.Mapper[*DNSRecordBinding] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*DNSRecordBinding, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *dnsRecordBindingPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "game_server_id":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.GameServerID }})
			case "relative_name":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.RelativeName }})
			case "owned_provider_record_id":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.OwnedProviderRecordID }})
			case "owned_fqdn":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.OwnedFQDN }})
			case "owned_record_type":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.OwnedRecordType }})
			case "owned_value":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.OwnedValue }})
			case "owned_ttl":
				targets = append(targets, target{i, func(b *dnsRecordBindingPreloadBuf) any { return &b.OwnedTTL }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(dnsRecordBindingPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*DNSRecordBinding, error) {
				buf := link.(*dnsRecordBindingPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.GameServerID.IsValue()) &&
					!(buf.RelativeName.IsValue()) &&
					!(buf.OwnedProviderRecordID.IsValue()) &&
					!(buf.OwnedFQDN.IsValue()) &&
					!(buf.OwnedRecordType.IsValue()) &&
					!(buf.OwnedValue.IsValue()) &&
					!(buf.OwnedTTL.IsValue()) {
					return nil, nil
				}

				o := new(DNSRecordBinding)
				if buf.GameServerID.IsValue() {
					o.GameServerID = buf.GameServerID.MustGet()
				}
				if buf.RelativeName.IsValue() {
					o.RelativeName = buf.RelativeName.MustGet()
				}
				o.OwnedProviderRecordID = buf.OwnedProviderRecordID
				o.OwnedFQDN = buf.OwnedFQDN
				o.OwnedRecordType = buf.OwnedRecordType
				o.OwnedValue = buf.OwnedValue
				o.OwnedTTL = buf.OwnedTTL
				return o, nil
			}
	}
}

func (o *DNSRecordBinding) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServer":
		rel, ok := retrieved.(*GameServer)
		if !ok {
			return fmt.Errorf("dnsRecordBinding cannot load %T as %q", retrieved, name)
		}

		o.R.GameServer = rel
		o.R.Loaded.GameServer = true

		if rel != nil {
			rel.R.DNSRecordBinding = o
			rel.R.Loaded.DNSRecordBinding = true
		}
		return nil
	default:
		return fmt.Errorf("dnsRecordBinding has no relationship %q", name)
	}
}

type dnsRecordBindingPreloader struct {
	GameServer func(...sqlite.PreloadOption) sqlite.Preloader
}

func buildDNSRecordBindingPreloader() dnsRecordBindingPreloader {
	return dnsRecordBindingPreloader{
		GameServer: func(opts ...sqlite.PreloadOption) sqlite.Preloader {
			return sqlite.Preload[*GameServer, GameServerSlice](sqlite.PreloadRel{
				Name: "GameServer",
				Sides: []sqlite.PreloadSide{
					{
						From:        DNSRecordBindings,
						To:          GameServers,
						FromColumns: []string{"game_server_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, GameServers.Columns.Names(), gameServerScanMapperNullable, opts...)
		},
	}
}

