// LoadGameServer loads the dnsRecordBinding's GameServer into the .R struct
func (o *DNSRecordBinding) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServer = nil
	o.R.Loaded.GameServer = false

	related, err := o.GameServer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.DNSRecordBinding = o
	related.R.Loaded.DNSRecordBinding = true

	o.R.GameServer = related
	o.R.Loaded.GameServer = true
	return nil
}

// LoadGameServer loads the dnsRecordBinding's GameServer into the .R struct
func (os DNSRecordBindingSlice) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.GameServer = nil
		o.R.Loaded.GameServer = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	dnsRecordBindingByKey := make(map[string][]*DNSRecordBinding, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		dnsRecordBindingByKey[o.GameServerID] = append(dnsRecordBindingByKey[o.GameServerID], o)
	}

	for _, rel := range gameServers {

		owners, ok := dnsRecordBindingByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.GameServer != nil {
				continue
			}

			rel.R.DNSRecordBinding = o
			rel.R.Loaded.DNSRecordBinding = true

			o.R.GameServer = rel

		}
	}

	return nil
}

type dnsRecordBindingJoins[Q dialect.Joinable] struct {
	typ        string
	GameServer modAs[Q, gameServerColumns]
}

func (j dnsRecordBindingJoins[Q]) aliasedAs(alias string) dnsRecordBindingJoins[Q] {
	return buildDNSRecordBindingJoins[Q](buildDNSRecordBindingColumns(alias), j.typ)
}

func buildDNSRecordBindingJoins[Q dialect.Joinable](cols dnsRecordBindingColumns, typ string) dnsRecordBindingJoins[Q] {
	return dnsRecordBindingJoins[Q]{
		typ: typ,
		GameServer: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.GameServerID),
					))
				}

				return mods
			},
		},
	}
}
